import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import humanTime from 'flarum/common/helpers/humanTime';
const t = (key, params) => app.translator.trans(`ernestdefoe-chronicle.forum.${key}`, params);
const ICONS = {
  discussion: 'far fa-comments',
  reply: 'fas fa-reply',
  like: 'far fa-thumbs-up',
  best_answer: 'fas fa-check',
  badge: 'fas fa-award',
  joined: 'fas fa-user-plus'
};

// The chips, in this order. "Joined" has none: it is one line at the very end.
const FILTERS = ['discussion', 'reply', 'like', 'best_answer', 'badge'];

/**
 * A member's activity: everything they have done, newest first, grouped by day.
 */
export default class ChroniclePage extends UserPage {
  oninit(vnode) {
    super.oninit(vnode);
    this.items = [];
    this.next = null;
    this.types = null;
    this.filter = 'all';
    this.loading = true;
    this.failed = false;
    this.request = 0;
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    this.refresh();
  }
  refresh() {
    this.items = [];
    this.next = null;
    this.load();
  }
  load(cursor) {
    const ticket = ++this.request;
    const params = {};
    if (this.filter !== 'all') params.types = this.filter;
    if (cursor) {
      params.before = cursor.before;
      params.key = cursor.key;
    }
    this.loading = true;
    this.failed = false;
    return app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/chronicle/${this.user.id()}`,
      params
    }).then(response => {
      // A chip clicked while this page was on its way makes it stale.
      if (ticket !== this.request) return;
      this.items = this.items.concat(response.items || []);
      this.next = response.next || null;
      if (!this.types) this.types = response.types || [];
    }).catch(() => {
      if (ticket === this.request) this.failed = true;
    }).finally(() => {
      if (ticket !== this.request) return;
      this.loading = false;
      m.redraw();
    });
  }
  choose(filter) {
    if (filter === this.filter) return;
    this.filter = filter;
    this.refresh();
  }
  content() {
    return m("div", {
      className: "Chronicle"
    }, this.filters(), this.feed());
  }
  filters() {
    const offered = FILTERS.filter(type => (this.types || []).includes(type));

    // One kind of item only: there is nothing to choose between.
    if (offered.length < 2) return null;
    return m("div", {
      className: "Chronicle-filters",
      role: "toolbar",
      "aria-label": t('filters.label')
    }, ['all', ...offered].map(type => m("button", {
      type: "button",
      className: 'Chronicle-chip' + (this.filter === type ? ' is-active' : ''),
      "aria-pressed": this.filter === type ? 'true' : 'false',
      onclick: () => this.choose(type)
    }, type !== 'all' ? m(Icon, {
      name: ICONS[type]
    }) : null, m("span", null, t(`filters.${type}`)))));
  }
  feed() {
    if (this.items.length === 0) {
      if (this.loading) return m(LoadingIndicator, null);
      if (this.failed) return this.failure();
      return m("div", {
        className: "Chronicle-empty"
      }, m(Icon, {
        name: "fas fa-stream"
      }), m("p", null, this.filter === 'all' ? t('empty') : t('empty_filtered')));
    }
    return m("div", {
      className: "Chronicle-feed"
    }, this.days().map(day => m("section", {
      className: "Chronicle-day",
      key: day.key
    }, m("h3", {
      className: "Chronicle-dayTitle"
    }, day.label), m("ol", {
      className: "Chronicle-list"
    }, day.items.map(item => m("li", {
      className: `Chronicle-item Chronicle-item--${item.type}`,
      key: item.id
    }, this.item(item)))))), this.failed ? this.failure() : null, this.next && !this.failed ? m("div", {
      className: "Chronicle-more"
    }, m(Button, {
      className: "Button",
      loading: this.loading,
      onclick: () => this.load(this.next)
    }, t('load_more'))) : null);
  }
  failure() {
    return m("div", {
      className: "Chronicle-empty Chronicle-empty--failed"
    }, m("p", null, t('failed')), m(Button, {
      className: "Button",
      onclick: () => this.load(this.next && this.items.length ? this.next : null)
    }, t('retry')));
  }

  /** The items in runs of the same local day. */
  days() {
    const dayjs = window.dayjs;
    const today = dayjs().startOf('day');
    const yesterday = today.subtract(1, 'day');
    const days = [];
    this.items.forEach(item => {
      const date = dayjs(item.date);
      const key = date.format('YYYY-MM-DD');
      let day = days[days.length - 1];
      if (!day || day.date !== key) {
        let label;
        if (date.isSame(today, 'day')) label = t('today');else if (date.isSame(yesterday, 'day')) label = t('yesterday');else label = app.translator.formatDateTime(date, 'ernestdefoe-chronicle.forum.day_format');

        // Keyed by position too: an imported forum's join date can sit out of
        // order, and two runs of one day must not share a key.
        day = {
          key: `${key}-${days.length}`,
          date: key,
          label,
          items: []
        };
        days.push(day);
      }
      day.items.push(item);
    });
    return days;
  }
  item(item) {
    const showExcerpt = ['reply', 'discussion', 'best_answer'].includes(item.type) && item.excerpt;
    return [m("span", {
      className: "Chronicle-icon",
      "aria-hidden": "true"
    }, m(Icon, {
      name: ICONS[item.type] || 'fas fa-circle'
    })), m("div", {
      className: "Chronicle-body"
    }, m("div", {
      className: "Chronicle-line"
    }, m("span", {
      className: "Chronicle-sentence"
    }, this.sentence(item)), m("span", {
      className: "Chronicle-time"
    }, humanTime(new Date(item.date)))), showExcerpt ? m(Link, {
      className: "Chronicle-excerpt",
      href: this.postUrl(item)
    }, item.excerpt) : null)];
  }
  sentence(item) {
    const title = item.discussion ? m(Link, {
      className: "Chronicle-title",
      href: this.postUrl(item)
    }, item.discussion.title) : t('item.untitled');
    switch (item.type) {
      case 'like':
        return item.author ? t('item.like', {
          author: m("strong", null, item.author.displayName),
          title
        }) : t('item.like_no_author', {
          title
        });
      case 'badge':
        {
          const badge = item.badge || {};
          return t('item.badge', {
            badge: m("span", {
              className: "Chronicle-badge",
              style: {
                '--chronicle-badge-bg': badge.backgroundColor,
                '--chronicle-badge-fg': badge.iconColor
              }
            }, badge.icon ? m(Icon, {
              name: badge.icon
            }) : null, badge.name)
          });
        }
      case 'joined':
        return t('item.joined');
      default:
        return t(`item.${item.type}`, {
          title
        });
    }
  }
  postUrl(item) {
    if (!item.discussion) return '#';
    const number = item.postNumber || 1;
    return number > 1 ? app.route('discussion.near', {
      id: item.discussion.slug,
      near: number
    }) : app.route('discussion', {
      id: item.discussion.slug
    });
  }
}
flarum.reg.add('ernestdefoe-chronicle', 'forum/components/ChroniclePage', ChroniclePage);